tab1_cache = {}
tab2_cache = {}

def calc_num1(x):
    if x < 0:
        return 0
    if x < 2:
        return 1
    if x not in tab1_cache:
        sum_result = 0
        for j in range(x):
            sum_result += calc_num1(j) * calc_num1(x - 1 - j)
        tab1_cache[x] = sum_result
    return tab1_cache[x]

def calc_num2(x, y):
    if x < 0 or y <= 0 or x >= 2 ** (y - 1):
        return 0
    if x < 2:
        return 1
    if x < y:
        return calc_num1(x)
    if (x, y) not in tab2_cache:
        sum_result = 0
        for j in range(x):
            sum_result += calc_num2(j, y - 1) * calc_num2(x - 1 - j, y - 1)
        tab2_cache[(x, y)] = sum_result
    return tab2_cache[(x, y)]

a, b = map(int, raw_input().split())
print calc_num1(a) - calc_num2(a, b)
